-- ============================================================================
-- Ticket #30 — Symmetric cross-table enrichment filtering
-- Combined migration: apply this ONE file in the Supabase SQL editor.
-- Order matters: virtual-columns.sql defines the leaf predicates the others call.
-- Generated by concatenating the 5 updated lib/data/*.sql files.
-- ============================================================================


-- ============================================================================
-- SECTION: lib/data/virtual-columns.sql
-- ============================================================================

-- Run once in the Supabase SQL editor (see docs/adr/0002-virtual-column-enrichment-filtering.md,
-- spec issue #31, ticket #33).
--
-- The single place a virtual-column predicate over `custom_data` is
-- evaluated, so the filtered list/count, the facet computation, CSV export,
-- and the Clay/GHL push all agree on what a filter matches — see
-- lib/data/companies.ts / lib/data/people.ts for the callers, and
-- canonical-columns.sql / people-canonical-columns.sql for the facet RPCs
-- this threads into. Ticket #33 introduces this seam with no operator UI;
-- follow-on tickets (#34 Text, #35 Number/Date, #36 Boolean/List) add the
-- app-side wiring that populates `filters.virtualFilters`.

-- Ticket #116 revised its first draft of the contains/not_contains chip-input
-- helpers mid-review (a nested CASE inside text_filter_matches/list_filter_matches
-- knocked those functions off Postgres's inliner — see text_contains_matches'
-- comment below) — drop the earlier names so a re-run of this file doesn't
-- leave them behind as orphaned, unused functions.
DROP FUNCTION IF EXISTS text_contains_any(text, jsonb);
DROP FUNCTION IF EXISTS list_contains_any(jsonb, jsonb);

-- Empty-value normalization, defined once and reused by every "is empty" /
-- "is not empty" case below. Mirrors (but is not identical to) the simpler
-- display-only isEmptyValue in lib/data/custom-data.ts: filtering also treats
-- whitespace-only strings, the "-" sentinel, and unrendered Clay templates
-- ("{{ ... }}") as empty, since real enrichment data carries all three as
-- placeholder junk (see CONTEXT.md's "Empty (enrichment value)" glossary
-- entry). The string is trimmed once up front so a template with stray
-- surrounding whitespace ("  {{ x }}  ") normalizes the same as a clean one —
-- every branch below reads the trimmed text, not the raw one.
CREATE OR REPLACE FUNCTION is_empty_enrichment_value(v jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT
    v IS NULL
    OR v = 'null'::jsonb
    OR (jsonb_typeof(v) = 'array' AND jsonb_array_length(v) = 0)
    OR (
      jsonb_typeof(v) = 'string'
      AND (
        trim(both from (v #>> '{}')) = ''
        OR trim(both from (v #>> '{}')) = '-'
        OR trim(both from (v #>> '{}')) ~ '^\{\{.*\}\}$'
      )
    )
$$;

-- Cast-safe numeric read of an enrichment value: NULL (never an exception)
-- for anything that isn't a clean number, so a Number filter drops
-- non-numeric junk ("$10", "-", "{{ 0 }}", stray strings) instead of 500ing
-- the request (ADR-0002). Regex-guards before casting because Postgres has
-- no try_cast. Handles both a real JSON number and a numeric-looking string,
-- since the same custom_data key holds either shape across rows.
CREATE OR REPLACE FUNCTION enrichment_numeric(v jsonb) RETURNS numeric
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN v IS NULL THEN NULL
    WHEN jsonb_typeof(v) = 'number' THEN (v #>> '{}')::numeric
    WHEN jsonb_typeof(v) = 'string' AND (v #>> '{}') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (v #>> '{}')::numeric
    ELSE NULL
  END
$$;

-- Cast-safe ISO-date text read: NULL for anything that isn't a YYYY-MM-DD-
-- prefixed string. Comparison stays lexicographic on the returned text (not a
-- date cast) because ISO dates sort correctly as text and a text compare
-- can't throw on a malformed date the way a `::date` cast can (ADR-0002).
CREATE OR REPLACE FUNCTION enrichment_date_text(v jsonb) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN jsonb_typeof(v) = 'string' AND (v #>> '{}') ~ '^\d{4}-\d{2}-\d{2}' THEN (v #>> '{}')
    ELSE NULL
  END
$$;

-- Cast-safe uuid read: the uuid for a valid 8-4-4-4-12 hex string, else NULL
-- (never an exception). Mirrors enrichment_numeric/enrichment_date_text's
-- regex-guard-before-cast rule (ADR-0002: Postgres has no try_cast, and a
-- filter-derived value that can't be cast must exclude rather than 500 the
-- request). Used by the push-status filter (ticket #127) to cast the
-- URL-supplied `pushStatus.clientId` before the platform_pushes join — the
-- param is only validated as "non-empty" upstream (parsePushStatusFilter), so a
-- hand-edited `?pushClient=garbage` reaches here as junk and must not throw. A
-- NULL result makes `pp.client_id = NULL` match no push rows, so the filter
-- degrades to "unknown client" semantics (pushed → none, not_pushed → all)
-- rather than erroring. Kept `::uuid` (not text compare) so the client_id side
-- stays index-sargable against platform_pushes_client_platform_person_idx.
CREATE OR REPLACE FUNCTION safe_uuid(t text) RETURNS uuid
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN t ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN t::uuid
    ELSE NULL
  END
$$;

-- Evaluates one virtual-column filter `{key, type, operator, value}` against
-- a row's custom_data. Every branch is written so a mismatched/dirty value
-- excludes the row rather than raising — no PostgREST text-path lexicographic
-- comparison for Number (enrichment_numeric casts to numeric so 9 < 90
-- compares correctly), and Date stays a guarded text compare (see above).
-- List "contains" uses jsonb containment against the array's individual
-- members, not a substring/ILIKE match on the serialized array, so "a3"
-- never matches "a30". Named `_predicate_matches` (singular filter) to keep
-- it visually distinct from `virtual_filters_match` below (plural, ANDs many)
-- — the two are easy to transpose at a call site otherwise.
-- Rewritten (ticket #34 perf fix), in two steps, both confirmed with
-- EXPLAIN/EXPLAIN ANALYZE against the live ~110k-row companies table:
--
-- 1. Dropped the original `WITH p AS (...), v AS (...) SELECT ... FROM p, v`
--    CTE shape in favor of inlining every `data -> (f->>'key')` /
--    `f->>'type'` etc. read directly. This didn't turn out to be the actual
--    bottleneck on its own (Postgres 12+ auto-inlines non-recursive CTEs
--    into the surrounding query by default, so the `WITH` wasn't the
--    problem the way older Postgres-versions' folklore says it would be) —
--    kept anyway since it's simpler and reads the same value only once per
--    branch.
-- 2. The real bottleneck: whether *this* function itself gets inlined by
--    Postgres's planner into whatever query calls it. Postgres's
--    `LANGUAGE sql` function inliner (`inline_function()`) will fold a
--    function's body directly into the caller's plan as a plain expression
--    — but only below some function-body complexity; empirically, the
--    original single function with 5 outer `f->>'type'` branches x ~5
--    operators each (~24 total WHEN arms across nested CASEs) was NOT
--    inlined (confirmed via EXPLAIN: it always showed up as an opaque
--    `virtual_filter_predicate_matches(c.custom_data, vf.value)` function
--    call in the Filter, never expanded), while smaller versions of the same
--    shape (fewer branches) *did* inline cleanly into a plain Join Filter
--    expression. A non-inlined function called once per row of a ~110k-row
--    scan pays real per-call overhead (confirmed: an equivalent raw
--    predicate with no function layer at all scans all ~110k rows in ~69ms;
--    the non-inlined-function version timed out past statement_timeout for
--    the 'is'/'contains' operators). The fix is to keep every individual
--    function small enough to inline: this function is now a thin dispatch
--    by `f->>'type'` to five per-type helper functions below
--    (text/number/boolean/list/date), each simple enough on its own to
--    inline (verified individually), and Postgres inlines recursively — a
--    thin dispatcher that only calls already-inlinable functions is itself
--    inlinable, so the whole chain collapses into one plain filter
--    expression with no function-call overhead left, exactly like the
--    smaller test cases. Semantics (types/operators/branches) are
--    unchanged, only decomposed into smaller pieces.
--
-- LIVE PRODUCTION FINDING (later, verified empirically against the ~110k-row
-- production companies table): even after tickets #34 and #116, the six-arm
-- `text_filter_matches` STILL did not inline on production Postgres, and every
-- TEXT-type virtual filter kept full-scanning ~110k rows into statement_timeout
-- (57014, ~8s) — the "Failed to load companies" failure. The deployed function
-- bodies matched this file exactly (checked via pg_get_functiondef), so this
-- was NOT a stale deploy; text_filter_matches simply sat over the planner's
-- function-inlining size/complexity threshold on this server and stayed an
-- opaque per-row call. A decisive isolation test (a NONEXISTENT custom_data
-- key, so per-row data work is ~zero and identical across every type, over the
-- full table): text `is`/`is_not_empty` took ~8.2s, while number `is`, boolean
-- `is_true`, date `on`, and list `is_not_empty` each took ~1.2s — so only the
-- text helper was failing to inline. Crucially, `list_filter_matches` DID
-- inline (~1.2s) even though it transitively calls `list_contains_matches`,
-- whose OWN body contains a SubLink (`ARRAY(SELECT jsonb_array_elements_text
-- (...))`): a transitive reference to a SubLink-containing helper does NOT
-- block the caller's inlining. That rules out the SubLink chain
-- (text_contains_matches/jsonb_ilike_patterns) as the cause and pins it on the
-- one distinguishing factor — `text_filter_matches` was the LARGEST per-type
-- helper (6 operator arms; by far the most references to its `f`/`data` params)
-- and thus over the inliner's body-size threshold while the others stayed under
-- it. The fix (this file): decompose ONE step further, exactly mirroring the
-- `contains` -> text_contains_matches pattern — pull the `is`/`is_not` equality
-- out into the flat `text_equals_matches` helper so EVERY arm of
-- text_filter_matches is a single flat function call and its own body is small
-- enough to inline. Semantics are byte-identical (a pure planner-inlining fix;
-- see text_equals_matches' comment for the @>-containment equivalence). NOTE
-- this must be APPLIED BY HAND in the Supabase SQL editor (re-run this whole
-- file); the orchestrator verifies inlining via timing probes afterward.
-- Chip-input dispatch helper for Text contains/not_contains (ticket #116):
-- true iff `text_value` ILIKE-matches the scalar `value`, or (when `value` is
-- a jsonb array — the chip input's stacked keywords) ILIKE-matches *any* of
-- its elements. Kept as its own function, called as a single flat FuncExpr
-- from each of text_filter_matches' 'contains'/'not_contains' arms, rather
-- than inlined as a *nested* CASE directly in text_filter_matches' own body:
-- empirically, nesting a second CASE inside one arm was enough added branch
-- complexity to knock text_filter_matches itself off Postgres's inliner —
-- every arm in text_filter_matches' CASE must stay a single flat expression.
--
-- BUGFIX (categories/specialties contains 503, issue: statement_timeout 57014):
-- this helper's *first* draft put the array case's `EXISTS (...)` subquery
-- directly in this function's own body. That was wrong: Postgres's
-- inline_function() bails on ANY body with `hasSubLinks` set (an EXISTS
-- qualifies) — so text_contains_matches itself became a non-inlinable, opaque
-- per-row SQL-function call, exactly the failure mode this file documents for
-- virtual_filters_match. Every text `contains`/`not_contains` request (scalar
-- OR array, any key) then ran that opaque call once per row across the full
-- ~146k-row scan and blew past statement_timeout (reproduced live: scalar
-- `categories contains 'software'` timed out at ~8.3s / 57014, while the
-- inlinable `is`/`is_not_empty` on the same key stayed at the ~4.6s baseline).
-- Moving the EXISTS "down" into this helper kept text_filter_matches inlinable
-- but left *this* function opaque, which is just as slow.
--
-- The fix: keep this function's body SubLink-free so it inlines too, and push
-- the one unavoidable SubLink (turning a jsonb array into a wildcarded text[])
-- down one more level into jsonb_ilike_patterns below. Per-row work is then a
-- plain `ILIKE` (scalar) or a `ILIKE ANY (<text[]>)` ScalarArrayOpExpr (array)
-- — no SubLink, no SRF, no per-row opaque call — so the whole chain
-- (text_filter_matches -> text_contains_matches) folds into the caller's WHERE
-- as a flat expression, the same fully-inlined class every other operator here
-- already gets. jsonb_ilike_patterns stays opaque (it has the SubLink) but is
-- invoked with the constant filter `value` only in the array branch, over a
-- tiny chip-keyword array — not the ILIKE that runs per row. Semantics are
-- byte-identical: `ILIKE ANY` over `'%kw%'` patterns matches iff any keyword
-- is a substring, the exact "matches any of" the EXISTS expressed, and the
-- scalar branch is unchanged. Patterns are never NULL, so the result is always
-- a definite boolean (needed for the caller's NOT EXISTS AND-fold).

-- Builds the `'%kw%'` ILIKE-pattern text[] for a jsonb array of chip keywords.
-- Isolated here (not inlined into text_contains_matches) precisely because the
-- `ARRAY(SELECT ... FROM jsonb_array_elements_text(...))` it needs is a SubLink
-- — keeping it in its own function leaves text_contains_matches SubLink-free
-- and therefore inlinable (see the note above). No wildcard-escaping of the
-- keyword, matching the scalar branch's existing `'%' || value || '%'` exactly.
CREATE OR REPLACE FUNCTION jsonb_ilike_patterns(value jsonb) RETURNS text[]
LANGUAGE sql IMMUTABLE AS $$
  SELECT ARRAY(SELECT '%' || kw || '%' FROM jsonb_array_elements_text(value) AS kw)
$$;

CREATE OR REPLACE FUNCTION text_contains_matches(text_value text, value jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE jsonb_typeof(value)
    WHEN 'array' THEN text_value ILIKE ANY (jsonb_ilike_patterns(value))
    ELSE text_value ILIKE ('%' || (value #>> '{}') || '%')
  END
$$;

-- Flat 'is'/'is_not' equality helper for Text, extracted for the same
-- inlinability reason as text_contains_matches (see the LIVE PRODUCTION FINDING
-- above): body is a single flat expression, no CASE, no SubLink, so it inlines,
-- and text_filter_matches' 'is'/'is_not' arms become one flat function call
-- each instead of an inline `@>`/`to_jsonb` expression tree. Semantics are
-- byte-identical to the pre-decomposition `(f->'value') @> to_jsonb(row_text)`:
-- jsonb containment `@>` unifies both value shapes — an array `@>` the scalar
-- row value matches iff the value is any member (ticket #38's multi-select),
-- and — by Postgres's scalar-contains-equal-scalar rule — a scalar `@>` the row
-- value is plain equality, so the single-value case keeps its exact prior
-- semantics. `value` is the filter's `f->'value'`; `row_text` is the row's
-- coalesced scalar text (the caller supplies the missing-key COALESCE-to-'').
CREATE OR REPLACE FUNCTION text_equals_matches(row_text text, value jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT value @> to_jsonb(row_text)
$$;

CREATE OR REPLACE FUNCTION text_filter_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'operator'
    -- 'is'/'is_not' accept either a scalar value or a JSON array of values
    -- (ticket #38's multi-select over a low-cardinality field's real distinct
    -- values), delegated to text_equals_matches above (kept flat — see the
    -- LIVE PRODUCTION FINDING note). The row value is coalesced to '' (missing
    -- key) so 'is_not' still includes a row that lacks the key, matching the
    -- pre-#38 `<>` behavior — the COALESCE stays here (not in the helper) so
    -- this arm reads byte-identically to the pre-decomposition expression.
    WHEN 'is' THEN text_equals_matches(COALESCE((data -> (f->>'key')) #>> '{}', ''), f->'value')
    WHEN 'is_not' THEN NOT text_equals_matches(COALESCE((data -> (f->>'key')) #>> '{}', ''), f->'value')
    -- 'contains'/'not_contains' additionally accept a JSON array of keywords
    -- (ticket #116's chip input): "matches any of" / "matches none of",
    -- delegated to text_contains_matches above (kept flat — see its comment).
    WHEN 'contains' THEN text_contains_matches(COALESCE((data -> (f->>'key')) #>> '{}', ''), f->'value')
    WHEN 'not_contains' THEN NOT text_contains_matches(COALESCE((data -> (f->>'key')) #>> '{}', ''), f->'value')
    WHEN 'is_empty' THEN is_empty_enrichment_value(data -> (f->>'key'))
    WHEN 'is_not_empty' THEN NOT is_empty_enrichment_value(data -> (f->>'key'))
    ELSE false
  END
$$;

CREATE OR REPLACE FUNCTION number_filter_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'operator'
    WHEN 'is' THEN enrichment_numeric(data -> (f->>'key')) IS NOT NULL AND enrichment_numeric(data -> (f->>'key')) = enrichment_numeric(f->'value')
    WHEN 'is_not' THEN enrichment_numeric(data -> (f->>'key')) IS NOT NULL AND enrichment_numeric(data -> (f->>'key')) <> enrichment_numeric(f->'value')
    WHEN 'gt' THEN enrichment_numeric(data -> (f->>'key')) IS NOT NULL AND enrichment_numeric(data -> (f->>'key')) > enrichment_numeric(f->'value')
    WHEN 'lt' THEN enrichment_numeric(data -> (f->>'key')) IS NOT NULL AND enrichment_numeric(data -> (f->>'key')) < enrichment_numeric(f->'value')
    WHEN 'between' THEN
      enrichment_numeric(data -> (f->>'key')) IS NOT NULL
      AND enrichment_numeric(data -> (f->>'key')) BETWEEN enrichment_numeric((f->'value')->0) AND enrichment_numeric((f->'value')->1)
    ELSE false
  END
$$;

CREATE OR REPLACE FUNCTION boolean_filter_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'operator'
    WHEN 'is_true' THEN
      CASE jsonb_typeof(data -> (f->>'key'))
        WHEN 'boolean' THEN ((data -> (f->>'key')) #>> '{}') = 'true'
        WHEN 'string' THEN lower((data -> (f->>'key')) #>> '{}') IN ('true', 'yes', '1')
        ELSE false
      END
    WHEN 'is_false' THEN
      CASE jsonb_typeof(data -> (f->>'key'))
        WHEN 'boolean' THEN ((data -> (f->>'key')) #>> '{}') = 'false'
        WHEN 'string' THEN lower((data -> (f->>'key')) #>> '{}') IN ('false', 'no', '0')
        ELSE false
      END
    ELSE false
  END
$$;

-- contains/not_contains use the `?` (jsonb "does this string exist as a
-- top-level array element") operator rather than `@> jsonb_build_array(...)`
-- (ticket #36 perf fix, confirmed against the live ~110k-row companies
-- table): `?` is a plain built-in binary operator with no per-row function
-- call, while `jsonb_build_array` is invoked fresh on every row to wrap the
-- target value before the containment check — measured to push the full
-- scan past statement_timeout where `?` completes in line with the other
-- per-type helpers (text/number/date/boolean). Semantics are identical for
-- this case since the filter value is always a scalar string (never a
-- multi-value array like Text's is/is_not, ticket #38) — `?` compares each
-- array member by exact string equality, so "a3" still never matches "a30".
--
-- contains/not_contains are wrapped in COALESCE (ticket #36 correctness fix,
-- found via integration test: a near-string that should never match came
-- back with ~98k false positives, exactly the count of rows where the key
-- is absent from custom_data entirely). `jsonb_typeof(NULL)` is SQL NULL,
-- not a string, so `jsonb_typeof(data -> key) = 'array'` is NULL — not
-- false — whenever the key is missing, and `NULL AND ...` is NULL too. That
-- NULL predicate breaks companies_matching_virtual_filters' `NOT EXISTS
-- (... WHERE NOT virtual_filter_predicate_matches(...))` AND-semantics:
-- `NOT NULL` is NULL, so a row with a NULL predicate is never excluded by
-- the EXISTS check, which means it's treated as matching every filter
-- regardless of value. text/number/date/boolean already avoid this (via
-- COALESCE, explicit IS NOT NULL guards, or an ELSE false terminating every
-- CASE) — list's contains/not_contains were the one branch that could still
-- evaluate to NULL instead of a definite boolean. COALESCE forces a missing
-- key to definite false for contains (no array, so it can't contain
-- anything) and definite true for not_contains (same reasoning Text's
-- not_contains already applies to a missing value via its own COALESCE).
-- Chip-input dispatch helper for List contains (ticket #116): true iff
-- `data_value` (the row's array) is a jsonb array containing the scalar
-- `value` as an exact member, or — when `value` is itself a jsonb array, the
-- chip input's stacked keywords — shares *any* member with it. The array
-- branch uses `?|` ("does any of these text[] elements exist as a top-level
-- array element"), the same operator ticket #36 chose over
-- `jsonb_build_array` for the scalar case: a plain built-in binary op, no
-- per-row function call, once `value` is materialized to a text[]. Kept as
-- its own function — called as a single flat FuncExpr from list_filter_matches'
-- 'contains'/'not_contains' arms, not a *nested* CASE inside its own body —
-- for the same reason as text_contains_matches above: a second CASE nested in
-- one arm was enough to knock the whole calling function off Postgres's
-- inliner in the Text case (confirmed via EXPLAIN ANALYZE against the live
-- table), and every arm here must stay flat to avoid the same regression.
-- `ARRAY(SELECT jsonb_array_elements_text(...))` is itself a SubLink, so it
-- has to live in a called function rather than list_filter_matches' own body
-- either way. Missing-key COALESCE reasoning matches ticket #36's original
-- single-value branches (false for contains, true for not_contains via the
-- NOT at the call site — see below).
CREATE OR REPLACE FUNCTION list_contains_matches(data_value jsonb, value jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE jsonb_typeof(value)
    WHEN 'array' THEN COALESCE(
      jsonb_typeof(data_value) = 'array' AND data_value ?| ARRAY(SELECT jsonb_array_elements_text(value)),
      false
    )
    ELSE COALESCE(jsonb_typeof(data_value) = 'array' AND data_value ? (value #>> '{}'), false)
  END
$$;

CREATE OR REPLACE FUNCTION list_filter_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'operator'
    WHEN 'contains' THEN list_contains_matches(data -> (f->>'key'), f->'value')
    WHEN 'not_contains' THEN NOT list_contains_matches(data -> (f->>'key'), f->'value')
    WHEN 'is_empty' THEN is_empty_enrichment_value(data -> (f->>'key'))
    WHEN 'is_not_empty' THEN NOT is_empty_enrichment_value(data -> (f->>'key'))
    ELSE false
  END
$$;

CREATE OR REPLACE FUNCTION date_filter_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'operator'
    WHEN 'on' THEN enrichment_date_text(data -> (f->>'key')) IS NOT NULL AND enrichment_date_text(data -> (f->>'key')) = enrichment_date_text(f->'value')
    WHEN 'before' THEN enrichment_date_text(data -> (f->>'key')) IS NOT NULL AND enrichment_date_text(data -> (f->>'key')) < enrichment_date_text(f->'value')
    WHEN 'after' THEN enrichment_date_text(data -> (f->>'key')) IS NOT NULL AND enrichment_date_text(data -> (f->>'key')) > enrichment_date_text(f->'value')
    WHEN 'between' THEN
      enrichment_date_text(data -> (f->>'key')) IS NOT NULL
      AND enrichment_date_text(data -> (f->>'key')) BETWEEN enrichment_date_text((f->'value')->0) AND enrichment_date_text((f->'value')->1)
    ELSE false
  END
$$;

CREATE OR REPLACE FUNCTION virtual_filter_predicate_matches(data jsonb, f jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE f->>'type'
    WHEN 'text' THEN text_filter_matches(data, f)
    WHEN 'number' THEN number_filter_matches(data, f)
    WHEN 'boolean' THEN boolean_filter_matches(data, f)
    WHEN 'list' THEN list_filter_matches(data, f)
    WHEN 'date' THEN date_filter_matches(data, f)
    ELSE false
  END
$$;

-- Folds a grouped virtual-filter set `{combinator, groups:[{combinator,
-- conditions:[...]}]}` (ticket #117) into one boolean: conditions combine
-- inside a group with the group's combinator (AND/OR), and groups combine at
-- the top with the set's combinator. AND folds are `NOT EXISTS (... WHERE NOT
-- predicate)` (all must match); OR folds are `EXISTS (... WHERE predicate)`
-- (any matches). An empty/null set (`->'groups'` absent or []) matches every
-- row — the no-virtual-filters-active case that keeps native filtering
-- unchanged (top-level AND over zero groups is `NOT EXISTS over empty` = true;
-- callers additionally short-circuit on `jsonb_array_length(...->'groups') =
-- 0` so a top-level *OR* over zero groups can't collapse to "match nothing").
-- A single AND group of ANDed conditions reproduces the pre-#117 flat-AND
-- result exactly (backward compatible).
--
-- Kept as the single documented definition of "how a grouped virtual filter
-- set matches", but every caller below (list, facet, and discovery RPCs alike)
-- inlines this same nested-EXISTS shape directly into its own WHERE clause
-- instead of calling this function, because a `LANGUAGE sql` function whose
-- body contains an EXISTS (a SubLink) can never be inlined by the planner (PG's
-- inline_function() bails out whenever hasSubLinks is set) — calling it from
-- another query's per-row predicate means every row pays the overhead of a
-- full opaque SQL-function call that internally re-executes a subquery,
-- confirmed via EXPLAIN ANALYZE to cost ~100x a plain in-line predicate over
-- the same ~110k rows (69ms vs 8s+/timeout). The leaf
-- `virtual_filter_predicate_matches` has no SubLink in its body, so once it's
-- the only function call left in the inlined chain the planner folds its CASE
-- directly into each EXISTS' WHERE clause. First caught in the two
-- list-filtering RPCs (ticket #34 perf fix); the facet RPCs
-- (company_filter_options/person_filter_options) and the discovery RPCs
-- (company_enrichment_fields/person_enrichment_fields) had the same bug and
-- were fixed the same way later (ticket #37 perf fix) — no caller should
-- reference this function directly.
CREATE OR REPLACE FUNCTION virtual_filters_match(data jsonb, filters jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT
    COALESCE(jsonb_array_length(filters->'groups'), 0) = 0
    OR CASE WHEN COALESCE(filters->>'combinator', 'and') = 'or' THEN
      EXISTS (
        SELECT 1 FROM jsonb_array_elements(filters->'groups') AS grp
        WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
            EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                    WHERE virtual_filter_predicate_matches(data, cond))
          ELSE
            NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE NOT virtual_filter_predicate_matches(data, cond))
          END
      )
    ELSE
      NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(filters->'groups') AS grp
        WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
            EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                    WHERE virtual_filter_predicate_matches(data, cond))
          ELSE
            NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE NOT virtual_filter_predicate_matches(data, cond))
          END)
      )
    END
$$;

-- Resolves the id set a request's *entire* filter set (native + virtual)
-- narrows to, in one scan. Takes the same jsonb shape company_filter_options
-- does (lib/data/companies.ts toFilterOptionsRpcPayload) and applies the
-- identical native predicate (search / employee size / niche / source /
-- industry / country / email+phone presence / emailStatus / phoneType —
-- mirrors applyCompanyFilters and company_filter_options' `base` CTE)
-- ANDed with the virtual-filter predicate. Applying the native filters here
-- too (not just the virtual half) matters: without them this would scan the
-- *whole* companies table on every virtual-filtered request regardless of
-- how narrow the native filters already are, instead of the same bounded
-- working set the native filters produce — which is what "no path pays for
-- a second scan" (ticket #33) actually requires. The companies/people list,
-- export, and Clay/GHL push functions (lib/data/companies.ts,
-- lib/data/people.ts) call this only when `filters.virtualFilters` is
-- non-empty, then intersect via `.in("id", ids)`; when no virtual filter is
-- active they skip this entirely and existing native-filtering behavior is
-- unchanged.
--
-- ticket #34 perf fix: the virtual-filter AND-across-filters check is
-- inlined here as `NOT EXISTS (... WHERE NOT virtual_filter_predicate_matches
-- (...))` directly in this function's own WHERE clause, rather than calling
-- the shared `virtual_filters_match` helper. Calling `virtual_filters_match`
-- from here (as ticket #33 originally did) meant every one of the ~110k
-- company rows paid the cost of an opaque, non-inlinable SQL-function call:
-- Postgres's planner will never inline a `LANGUAGE sql` function whose body
-- contains a SubLink (an `EXISTS (...)`  qualifies), so each row's check ran
-- as a full nested query execution rather than a plain filter expression —
-- confirmed via EXPLAIN ANALYZE (an equivalent raw predicate with no
-- function layer at all scanned all ~110k rows in ~69ms; the
-- virtual_filters_match-wrapped version timed out past Postgres's
-- statement_timeout on the same table for the 'is'/'contains' operators).
-- `virtual_filter_predicate_matches` itself has no CTE/SubLink/aggregate in
-- its body, so once it's the *only* function call in the chain (not nested
-- inside another opaque function), the planner inlines its CASE expression
-- directly into this EXISTS subquery's WHERE clause, and the whole thing
-- runs as ordinary per-row filter evaluation — no per-row function-call
-- overhead left. `virtual_filters_match` itself is kept only as the
-- documented reference definition — the facet RPCs
-- (company_filter_options/person_filter_options in canonical-columns.sql)
-- and the discovery RPCs (company_enrichment_fields/person_enrichment_fields
-- in enrichment-fields.sql) had the same non-inlinable-call bug and were
-- fixed the same way later (ticket #37 perf fix); no caller should reference
-- `virtual_filters_match` directly.
CREATE OR REPLACE FUNCTION companies_matching_virtual_filters(filters jsonb DEFAULT '{}'::jsonb)
RETURNS TABLE(id uuid) LANGUAGE sql STABLE AS $$
  WITH params AS (
    SELECT
      NULLIF(trim(both from (filters->>'search')), '') AS search,
      (filters->>'employeeMin')::int AS emp_min,
      (filters->>'employeeMax')::int AS emp_max,
      COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
      COALESCE(filters->>'email', 'any') AS email_filter,
      COALESCE(filters->>'phone', 'any') AS phone_filter,
      COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
      -- Push-status filter (ticket #127), extracted once here (not re-dug per
      -- use site). `pushStatus` absent or inactive (JSON null) -> all three are
      -- NULL -> the predicate's CASE falls to ELSE true, a no-op byte-identical
      -- to pre-#127 behavior. Present -> {clientId, platform, status}; clientId
      -- is cast cast-safe via safe_uuid (URL-supplied, only "non-empty"-checked
      -- upstream, so it must not throw — see safe_uuid).
      filters#>>'{pushStatus,status}' AS push_status_kind,
      filters#>>'{pushStatus,platform}' AS push_platform,
      safe_uuid(filters#>>'{pushStatus,clientId}') AS push_client_id,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
  )
  SELECT c.id
  FROM companies c, params p
  WHERE
    (p.search IS NULL OR c.company_name ILIKE '%' || p.search || '%' OR c.domain ILIKE '%' || p.search || '%')
    AND (
      CASE
        WHEN p.emp_min IS NOT NULL OR p.emp_max IS NOT NULL THEN
          (p.emp_min IS NULL OR c.employee_count >= p.emp_min)
          AND (p.emp_max IS NULL OR c.employee_count <= p.emp_max)
        WHEN jsonb_array_length(p.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(p.emp_ranges) AS r(min_v int, max_v int)
            WHERE c.employee_count >= r.min_v AND (r.max_v IS NULL OR c.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (p.email_filter = 'any'
      OR (p.email_filter = 'not_empty' AND c.email IS NOT NULL AND c.email <> '')
      OR (p.email_filter = 'empty' AND (c.email IS NULL OR c.email = '')))
    AND (p.phone_filter = 'any'
      OR (p.phone_filter = 'not_empty' AND c.phone IS NOT NULL AND c.phone <> '')
      OR (p.phone_filter = 'empty' AND (c.phone IS NULL OR c.phone = '')))
    AND (cardinality(p.niche_exc) = 0 OR c.niche IS NULL OR NOT (c.niche = ANY(p.niche_exc)))
    AND (cardinality(p.niche_inc) = 0 OR c.niche = ANY(p.niche_inc))
    AND (cardinality(p.source_exc) = 0 OR c.source_tokens IS NULL OR NOT (c.source_tokens && p.source_exc))
    AND (cardinality(p.source_inc) = 0 OR (c.source_tokens IS NOT NULL AND c.source_tokens && p.source_inc))
    AND (cardinality(p.industry_exc) = 0 OR c.industry_id IS NULL OR NOT (c.industry_id = ANY(p.industry_exc)))
    AND (cardinality(p.industry_inc) = 0 OR c.industry_id = ANY(p.industry_inc))
    AND (cardinality(p.country_exc) = 0 OR c.country_id IS NULL OR NOT (c.country_id = ANY(p.country_exc)))
    AND (cardinality(p.country_inc) = 0 OR c.country_id = ANY(p.country_inc))
    AND (cardinality(p.emailstatus_exc) = 0 OR c.email_status IS NULL OR NOT (c.email_status = ANY(p.emailstatus_exc)))
    AND (cardinality(p.emailstatus_inc) = 0 OR c.email_status = ANY(p.emailstatus_inc))
    AND (cardinality(p.phonetype_exc) = 0 OR c.phone_type IS NULL OR NOT (c.phone_type = ANY(p.phonetype_exc)))
    AND (cardinality(p.phonetype_inc) = 0 OR c.phone_type = ANY(p.phonetype_inc))
    -- Grouped virtual-filter fold (ticket #117), inlined per the perf note on
    -- virtual_filters_match — must stay in lockstep with the identical fold in
    -- people_matching_virtual_filters, company_filter_options /
    -- person_filter_options, and company_enrichment_fields /
    -- person_enrichment_fields (grep virtual_filter_predicate_matches).
    --
    -- Ticket #30 (symmetric cross-table enrichment filtering): each leaf call
    -- is a per-condition dispatch on `cond->>'source'` rather than a bare
    -- virtual_filter_predicate_matches(c.custom_data, cond) call. Absent
    -- source (or 'company') keeps the pre-#30 behavior byte-identical
    -- (ELSE branch). A person-sourced condition ('source' = 'person')
    -- evaluates over this company's linked people instead: 'any' matches if
    -- at least one linked person satisfies the leaf (correlated EXISTS,
    -- mirroring the push-status EXISTS pattern below); 'all' matches if the
    -- company has >=1 linked person (leading EXISTS guard, so a zero-people
    -- company never matches an "all" cross-table condition) AND no linked
    -- person fails the leaf (NOT EXISTS ... NOT ..., mirroring the AND-fold's
    -- own NOT EXISTS shape one level up). Still no SubLink-free requirement
    -- here: this whole dispatch is itself inside an EXISTS/NOT EXISTS already,
    -- so it doesn't need to individually inline — only the leaf
    -- virtual_filter_predicate_matches call (unchanged, still the one
    -- inlinable primitive) matters for perf.
    AND (
      COALESCE(jsonb_array_length(p.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(p.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END)
        )
      END
    )
    -- Push-status filter (ticket #127), company "has work left" semantics —
    -- keep in lockstep with company_filter_options' base CTE (canonical-columns.sql).
    -- not_pushed: >=1 linked person NOT yet pushed to this client/platform.
    -- pushed: has >=1 linked person AND none of them is un-pushed (every linked
    -- person already pushed). Absent/inactive filter -> push_status_kind NULL ->
    -- ELSE true (no-op). Inlined EXISTS/NOT EXISTS (not a wrapper fn) so the
    -- planner can use platform_pushes_client_platform_person_idx instead of an
    -- opaque per-row call.
    AND CASE p.push_status_kind
      WHEN 'not_pushed' THEN EXISTS (
        SELECT 1 FROM people pe
        WHERE pe.company_id = c.id
          AND NOT EXISTS (
            SELECT 1 FROM platform_pushes pp
            WHERE pp.person_id = pe.id
              AND pp.client_id = p.push_client_id
              AND pp.platform = p.push_platform
          )
      )
      WHEN 'pushed' THEN
        EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
        AND NOT EXISTS (
          SELECT 1 FROM people pe
          WHERE pe.company_id = c.id
            AND NOT EXISTS (
              SELECT 1 FROM platform_pushes pp
              WHERE pp.person_id = pe.id
                AND pp.client_id = p.push_client_id
                AND pp.platform = p.push_platform
            )
        )
      ELSE true
    END
  ORDER BY c.id
$$;

-- Mirrors companies_matching_virtual_filters for /people — same jsonb shape
-- as person_filter_options expects (lib/data/people.ts toFilterOptionsRpcPayload),
-- same reasoning for why native filters are re-applied here (bounds the scan
-- to the real working set instead of the whole people table).
CREATE OR REPLACE FUNCTION people_matching_virtual_filters(filters jsonb DEFAULT '{}'::jsonb)
RETURNS TABLE(id uuid) LANGUAGE sql STABLE AS $$
  WITH params AS (
    SELECT
      NULLIF(trim(both from (filters->>'search')), '') AS search,
      NULLIF(trim(both from (filters->>'jobTitle')), '') AS job_title,
      (filters->>'employeeMin')::int AS emp_min,
      (filters->>'employeeMax')::int AS emp_max,
      COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
      COALESCE(filters->>'email', 'any') AS email_filter,
      COALESCE(filters->>'phone', 'any') AS phone_filter,
      COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
      -- Push-status filter (ticket #127), extracted once here (not re-dug per
      -- use site). `pushStatus` absent or inactive (JSON null) -> all three are
      -- NULL -> the predicate's CASE falls to ELSE true, a no-op byte-identical
      -- to pre-#127 behavior. Present -> {clientId, platform, status}; clientId
      -- is cast cast-safe via safe_uuid (URL-supplied, only "non-empty"-checked
      -- upstream, so it must not throw — see safe_uuid).
      filters#>>'{pushStatus,status}' AS push_status_kind,
      filters#>>'{pushStatus,platform}' AS push_platform,
      safe_uuid(filters#>>'{pushStatus,clientId}') AS push_client_id,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
  )
  -- Ticket #30: LEFT JOIN (not INNER) so a person with no linked company
  -- (company_id NULL) still evaluates person-sourced conditions correctly —
  -- a company-sourced condition then reads co.custom_data as NULL, which
  -- virtual_filter_predicate_matches treats as no match, the correct outcome.
  SELECT p.id
  FROM people p LEFT JOIN companies co ON co.id = p.company_id, params pr
  WHERE
    (pr.search IS NULL OR p.full_name ILIKE '%' || pr.search || '%' OR p.email ILIKE '%' || pr.search || '%')
    AND (pr.job_title IS NULL OR p.job_title ILIKE '%' || pr.job_title || '%')
    AND (
      CASE
        WHEN pr.emp_min IS NOT NULL OR pr.emp_max IS NOT NULL THEN
          (pr.emp_min IS NULL OR p.employee_count >= pr.emp_min)
          AND (pr.emp_max IS NULL OR p.employee_count <= pr.emp_max)
        WHEN jsonb_array_length(pr.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(pr.emp_ranges) AS r(min_v int, max_v int)
            WHERE p.employee_count >= r.min_v AND (r.max_v IS NULL OR p.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (pr.email_filter = 'any'
      OR (pr.email_filter = 'not_empty' AND p.email IS NOT NULL AND p.email <> '')
      OR (pr.email_filter = 'empty' AND (p.email IS NULL OR p.email = '')))
    AND (pr.phone_filter = 'any'
      OR (pr.phone_filter = 'not_empty' AND p.phone IS NOT NULL AND p.phone <> '')
      OR (pr.phone_filter = 'empty' AND (p.phone IS NULL OR p.phone = '')))
    AND (cardinality(pr.niche_exc) = 0 OR p.niche_tokens IS NULL OR NOT (p.niche_tokens && pr.niche_exc))
    AND (cardinality(pr.niche_inc) = 0 OR (p.niche_tokens IS NOT NULL AND p.niche_tokens && pr.niche_inc))
    AND (cardinality(pr.source_exc) = 0 OR p.source_tokens IS NULL OR NOT (p.source_tokens && pr.source_exc))
    AND (cardinality(pr.source_inc) = 0 OR (p.source_tokens IS NOT NULL AND p.source_tokens && pr.source_inc))
    AND (cardinality(pr.industry_exc) = 0 OR p.industry_id IS NULL OR NOT (p.industry_id = ANY(pr.industry_exc)))
    AND (cardinality(pr.industry_inc) = 0 OR p.industry_id = ANY(pr.industry_inc))
    AND (cardinality(pr.country_exc) = 0 OR p.country_id IS NULL OR NOT (p.country_id = ANY(pr.country_exc)))
    AND (cardinality(pr.country_inc) = 0 OR p.country_id = ANY(pr.country_inc))
    AND (cardinality(pr.emailstatus_exc) = 0 OR p.email_status IS NULL OR NOT (p.email_status = ANY(pr.emailstatus_exc)))
    AND (cardinality(pr.emailstatus_inc) = 0 OR p.email_status = ANY(pr.emailstatus_inc))
    AND (cardinality(pr.phonetype_exc) = 0 OR p.phone_type IS NULL OR NOT (p.phone_type = ANY(pr.phonetype_exc)))
    AND (cardinality(pr.phonetype_inc) = 0 OR p.phone_type = ANY(pr.phonetype_inc))
    -- Grouped virtual-filter fold (ticket #117) — identical to the companies
    -- copy above; keep in lockstep with all six inlined copies.
    --
    -- Ticket #30: each leaf is a per-condition dispatch. Absent source (or
    -- 'person') keeps the pre-#30 behavior byte-identical (ELSE branch).
    -- 'source' = 'company' reads the LEFT-JOINed co.custom_data instead —
    -- people->company is one-to-one via company_id, so no quantifier is
    -- needed (unlike the company->people fan-out above).
    AND (
      COALESCE(jsonb_array_length(pr.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(pr.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END)
        )
      END
    )
    -- Push-status filter (ticket #127) — keep in lockstep with the same clause
    -- in person_filter_options' base CTE (people-canonical-columns.sql).
    -- pushed: person has a push row for this client/platform; not_pushed: none.
    -- Absent/inactive filter -> push_status_kind NULL -> ELSE true (byte-identical
    -- to pre-#127). Inlined semi/anti-join so
    -- platform_pushes_client_platform_person_idx is used.
    AND CASE pr.push_status_kind
      WHEN 'pushed' THEN EXISTS (
        SELECT 1 FROM platform_pushes pp
        WHERE pp.person_id = p.id
          AND pp.client_id = pr.push_client_id
          AND pp.platform = pr.push_platform
      )
      WHEN 'not_pushed' THEN NOT EXISTS (
        SELECT 1 FROM platform_pushes pp
        WHERE pp.person_id = p.id
          AND pp.client_id = pr.push_client_id
          AND pp.platform = pr.push_platform
      )
      ELSE true
    END
  ORDER BY p.id
$$;


-- ============================================================================
-- SECTION: lib/data/canonical-columns.sql
-- ============================================================================

-- Run once in the Supabase SQL editor (see docs/adr/0001-dbside-companies-list-via-app-owned-canonical-columns.md).
-- NOTE: on a fresh database, run virtual-columns.sql before this file —
-- company_filter_options below calls virtual_filter_predicate_matches, defined there.
--
-- Adds app-owned "canonical columns" so Postgres can filter, facet, and sort
-- the companies list directly instead of the app re-normalizing all ~87k rows
-- on every request. TypeScript stays the single source of truth for how a raw
-- value becomes canonical (lib/data/country.ts, industry.ts, source.ts) —
-- these columns are a cache of that output, written only by the import
-- pipeline (lib/import/push.ts, lib/import/migrations.sql) and the one-time
-- backfill (lib/import/backfill-canonical-columns.ts). If a column disagrees
-- with what normalize*() would produce for the current raw value, it's stale.

ALTER TABLE companies ADD COLUMN IF NOT EXISTS country_id text;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS industry_id text;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS source_tokens text[];

-- Plain CREATE INDEX (not CONCURRENTLY) so this whole file can be pasted and
-- run in one shot from the SQL editor, which wraps a paste in one transaction
-- CONCURRENTLY can't run inside. Trade-off: each statement takes a brief
-- write lock on companies instead of none — on ~87k rows that's on the order
-- of seconds, which is fine for a one-time manual migration (same trade-off
-- performance-indexes.sql calls out as the CONCURRENTLY alternative).
CREATE INDEX IF NOT EXISTS companies_country_id_idx
  ON companies (country_id);

CREATE INDEX IF NOT EXISTS companies_industry_id_idx
  ON companies (industry_id);

CREATE INDEX IF NOT EXISTS companies_source_tokens_gin_idx
  ON companies USING gin (source_tokens);

-- Composite sort index backing the DB-side list query's
-- `ORDER BY last_updated DESC, id`. performance-indexes.sql's single-column
-- companies_last_updated index is left in place rather than dropped here —
-- drops belong in a deliberate cleanup, not bundled into a feature migration.
CREATE INDEX IF NOT EXISTS companies_last_updated_id_idx
  ON companies (last_updated DESC, id);

-- RPC: bulk-write country_id/industry_id/source_tokens by id, used only by
-- the one-time backfill (lib/import/backfill-canonical-columns.ts). Unlike
-- import_bulk_update_companies, this unconditionally overwrites (no COALESCE)
-- since the backfill always recomputes fresh from that row's current raw
-- country/industry/source and only enqueues rows that actually changed.
CREATE OR REPLACE FUNCTION backfill_canonical_columns(updates jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  rec jsonb;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(updates) LOOP
    UPDATE companies SET
      country_id = rec->>'country_id',
      industry_id = rec->>'industry_id',
      source_tokens = ARRAY(SELECT jsonb_array_elements_text(rec->'source_tokens'))
    WHERE id = (rec->>'id')::uuid;
  END LOOP;
END;
$$;

-- RPC: all six /companies facet dimensions in one query. Mirrors
-- getCompanyFilterOptions' in-app semantics exactly: each facet's own count
-- excludes its own filter but is scoped by every other active filter, and the
-- base scan (search / employee size / email+phone presence / virtual-column
-- filters) applies to every facet unconditionally. `filters` is a
-- JSON-serialized CompanyListFilters (see lib/data/companies.ts
-- toFilterOptionsRpcPayload) — include/exclude id lists come straight from
-- the client, already canonical, so no alias table is needed here; only
-- ids/counts are returned, labels are attached back in TS
-- (sourceLabel/industryLabel/countryLabel) so the alias/label tables stay
-- single-edit-point in TypeScript. `virtualFilters` (ticket #33, see
-- virtual-columns.sql) is folded into the same base scan via an inlined
-- `NOT EXISTS (... virtual_filter_predicate_matches ...)` (ticket #37 perf
-- fix — calling through the `virtual_filters_match` wrapper here timed out at
-- scale, same non-inlinable-SubLink issue documented in virtual-columns.sql
-- next to `companies_matching_virtual_filters`), so facet counts share the
-- exact predicate the list/export/push seam uses — never a second,
-- independently-maintained copy.
CREATE OR REPLACE FUNCTION company_filter_options(filters jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE sql STABLE AS $$
WITH params AS (
  SELECT
    NULLIF(trim(both from (filters->>'search')), '') AS search,
    (filters->>'employeeMin')::int AS emp_min,
    (filters->>'employeeMax')::int AS emp_max,
    COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
    COALESCE(filters->>'email', 'any') AS email_filter,
    COALESCE(filters->>'phone', 'any') AS phone_filter,
    COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
    -- Push-status filter (ticket #127), extracted once — clientId cast cast-safe
    -- via safe_uuid (virtual-columns.sql). Absent/inactive -> all NULL -> no-op.
    filters#>>'{pushStatus,status}' AS push_status_kind,
    filters#>>'{pushStatus,platform}' AS push_platform,
    safe_uuid(filters#>>'{pushStatus,clientId}') AS push_client_id,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
),
-- MATERIALIZED forces one scan of `companies`, reused by all six facet
-- subqueries below instead of six independent scans.
base AS MATERIALIZED (
  SELECT c.niche, c.industry_id, c.country_id, c.source_tokens, c.email_status, c.phone_type
  FROM companies c, params p
  WHERE
    (p.search IS NULL OR c.company_name ILIKE '%' || p.search || '%' OR c.domain ILIKE '%' || p.search || '%')
    AND (
      CASE
        WHEN p.emp_min IS NOT NULL OR p.emp_max IS NOT NULL THEN
          (p.emp_min IS NULL OR c.employee_count >= p.emp_min)
          AND (p.emp_max IS NULL OR c.employee_count <= p.emp_max)
        WHEN jsonb_array_length(p.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(p.emp_ranges) AS r(min_v int, max_v int)
            WHERE c.employee_count >= r.min_v AND (r.max_v IS NULL OR c.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (p.email_filter = 'any'
      OR (p.email_filter = 'not_empty' AND c.email IS NOT NULL AND c.email <> '')
      OR (p.email_filter = 'empty' AND (c.email IS NULL OR c.email = '')))
    AND (p.phone_filter = 'any'
      OR (p.phone_filter = 'not_empty' AND c.phone IS NOT NULL AND c.phone <> '')
      OR (p.phone_filter = 'empty' AND (c.phone IS NULL OR c.phone = '')))
    -- Grouped virtual-filter fold (ticket #117) — identical to the copies in
    -- virtual-columns.sql and enrichment-fields.sql; keep all six in lockstep
    -- or the facet counts diverge from the list (the #37 class of bug).
    --
    -- Ticket #30: per-condition dispatch — a person-sourced condition
    -- ('source' = 'person') reads this company's linked people instead of
    -- c.custom_data; see companies_matching_virtual_filters (virtual-columns.sql)
    -- for the full comment on the any/all quantifier semantics. Absent source
    -- (or 'company') is byte-identical to pre-#30 behavior.
    AND (
      COALESCE(jsonb_array_length(p.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(p.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END)
        )
      END
    )
    -- Push-status filter (ticket #127), company "has work left" semantics —
    -- identical to companies_matching_virtual_filters (virtual-columns.sql);
    -- keep in lockstep so facet counts match the list.
    AND CASE p.push_status_kind
      WHEN 'not_pushed' THEN EXISTS (
        SELECT 1 FROM people pe
        WHERE pe.company_id = c.id
          AND NOT EXISTS (
            SELECT 1 FROM platform_pushes pp
            WHERE pp.person_id = pe.id
              AND pp.client_id = p.push_client_id
              AND pp.platform = p.push_platform
          )
      )
      WHEN 'pushed' THEN
        EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
        AND NOT EXISTS (
          SELECT 1 FROM people pe
          WHERE pe.company_id = c.id
            AND NOT EXISTS (
              SELECT 1 FROM platform_pushes pp
              WHERE pp.person_id = pe.id
                AND pp.client_id = p.push_client_id
                AND pp.platform = p.push_platform
            )
        )
      ELSE true
    END
),
niches AS (
  SELECT base.niche AS id, count(*) AS count FROM base, params
  WHERE base.niche IS NOT NULL AND base.niche <> ''
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
  GROUP BY base.niche
),
sources AS (
  SELECT token AS id, count(*) AS count FROM (
    SELECT unnest(base.source_tokens) AS token
    FROM base, params
    WHERE (cardinality(params.niche_exc) = 0 OR base.niche IS NULL OR NOT (base.niche = ANY(params.niche_exc)))
      AND (cardinality(params.niche_inc) = 0 OR base.niche = ANY(params.niche_inc))
      AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
      AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
      AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
      AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
      AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
      AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
      AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
      AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
  ) t
  GROUP BY token
),
industries AS (
  SELECT base.industry_id AS id, count(*) AS count FROM base, params
  WHERE base.industry_id IS NOT NULL
    AND (cardinality(params.niche_exc) = 0 OR base.niche IS NULL OR NOT (base.niche = ANY(params.niche_exc)))
    AND (cardinality(params.niche_inc) = 0 OR base.niche = ANY(params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
  GROUP BY base.industry_id
),
countries AS (
  SELECT base.country_id AS id, count(*) AS count FROM base, params
  WHERE base.country_id IS NOT NULL
    AND (cardinality(params.niche_exc) = 0 OR base.niche IS NULL OR NOT (base.niche = ANY(params.niche_exc)))
    AND (cardinality(params.niche_inc) = 0 OR base.niche = ANY(params.niche_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
  GROUP BY base.country_id
),
email_statuses AS (
  SELECT base.email_status AS id, count(*) AS count FROM base, params
  WHERE base.email_status IS NOT NULL AND base.email_status <> ''
    AND (cardinality(params.niche_exc) = 0 OR base.niche IS NULL OR NOT (base.niche = ANY(params.niche_exc)))
    AND (cardinality(params.niche_inc) = 0 OR base.niche = ANY(params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
  GROUP BY base.email_status
),
phone_types AS (
  SELECT base.phone_type AS id, count(*) AS count FROM base, params
  WHERE base.phone_type IS NOT NULL AND base.phone_type <> ''
    AND (cardinality(params.niche_exc) = 0 OR base.niche IS NULL OR NOT (base.niche = ANY(params.niche_exc)))
    AND (cardinality(params.niche_inc) = 0 OR base.niche = ANY(params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
  GROUP BY base.phone_type
)
SELECT jsonb_build_object(
  'niches', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM niches), '[]'::jsonb),
  'sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM sources), '[]'::jsonb),
  'industries', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM industries), '[]'::jsonb),
  'countries', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM countries), '[]'::jsonb),
  'emailStatuses', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM email_statuses), '[]'::jsonb),
  'phoneTypes', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM phone_types), '[]'::jsonb)
);
$$;


-- ============================================================================
-- SECTION: lib/data/people-canonical-columns.sql
-- ============================================================================

-- Run once in the Supabase SQL editor (see docs/adr/0001-dbside-companies-list-via-app-owned-canonical-columns.md
-- and the "people" follow-up tickets #20-#25 that extend that same pattern to /people).
-- NOTE: on a fresh database, run virtual-columns.sql before this file —
-- person_filter_options below calls virtual_filter_predicate_matches, defined there.
--
-- Adds app-owned "canonical columns" so Postgres can filter, facet, and sort
-- the people list directly instead of the app re-normalizing/joining against
-- companies on every request. TypeScript stays the single source of truth for
-- how a raw value becomes canonical (lib/data/country.ts, source.ts,
-- lib/data/niche.ts's nichesFromTags) — these columns are a cache of that
-- output, written only by the import pipeline (lib/import/push.ts,
-- lib/import/migrations.sql), the company->people propagation RPC below, and
-- the one-time backfill (lib/import/backfill-canonical-columns-people.ts). If
-- a column disagrees with what those functions would produce for the row's
-- current raw data / linked company, it's stale.

ALTER TABLE people ADD COLUMN IF NOT EXISTS country_id text;
ALTER TABLE people ADD COLUMN IF NOT EXISTS source_tokens text[];
ALTER TABLE people ADD COLUMN IF NOT EXISTS industry_id text;
ALTER TABLE people ADD COLUMN IF NOT EXISTS employee_count int;
ALTER TABLE people ADD COLUMN IF NOT EXISTS company_linkedin_url text;
ALTER TABLE people ADD COLUMN IF NOT EXISTS niche_tokens text[];

-- Plain CREATE INDEX (not CONCURRENTLY) so this whole file can be pasted and
-- run in one shot from the SQL editor, which wraps a paste in one transaction
-- CONCURRENTLY can't run inside — same trade-off canonical-columns.sql makes.
CREATE INDEX IF NOT EXISTS people_country_id_idx
  ON people (country_id);

CREATE INDEX IF NOT EXISTS people_industry_id_idx
  ON people (industry_id);

CREATE INDEX IF NOT EXISTS people_source_tokens_gin_idx
  ON people USING gin (source_tokens);

CREATE INDEX IF NOT EXISTS people_niche_tokens_gin_idx
  ON people USING gin (niche_tokens);

-- Composite sort index backing the DB-side list query's
-- `ORDER BY last_updated DESC, id`, mirroring companies_last_updated_id_idx.
CREATE INDEX IF NOT EXISTS people_last_updated_id_idx
  ON people (last_updated DESC, id);

-- RPC: bulk-write all 6 canonical columns by id, used only by the one-time
-- backfill (lib/import/backfill-canonical-columns-people.ts). Unlike
-- import_bulk_update_people, this unconditionally overwrites (no COALESCE)
-- since the backfill always recomputes fresh from that row's current raw
-- data / linked company and only enqueues rows that actually changed.
CREATE OR REPLACE FUNCTION backfill_canonical_columns_people(updates jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  rec jsonb;
BEGIN
  FOR rec IN SELECT * FROM jsonb_array_elements(updates) LOOP
    UPDATE people SET
      country_id = rec->>'country_id',
      source_tokens = ARRAY(SELECT jsonb_array_elements_text(rec->'source_tokens')),
      industry_id = rec->>'industry_id',
      employee_count = CASE WHEN rec->>'employee_count' IS NOT NULL THEN (rec->>'employee_count')::int ELSE NULL END,
      company_linkedin_url = rec->>'company_linkedin_url',
      niche_tokens = ARRAY(SELECT jsonb_array_elements_text(rec->'niche_tokens'))
    WHERE id = (rec->>'id')::uuid;
  END LOOP;
END;
$$;

-- RPC: all six /people facet dimensions in one query. Mirrors
-- getPersonFilterOptions' in-app semantics exactly: each facet's own count
-- excludes its own filter but is scoped by every other active filter, and the
-- base scan (search / employee size / email+phone presence / jobTitle /
-- virtual-column filters) applies to every facet unconditionally.
-- `niche_tokens`/`source_tokens` are multi-valued (unnest + GIN), unlike
-- companies' scalar `niche` — a person with 2 niche tokens contributes to
-- both counts. `filters` is a JSON-serialized PersonListFilters (see
-- lib/data/people.ts toFilterOptionsRpcPayload); include/exclude id lists
-- come straight from the client, already canonical, so no alias table is
-- needed here — only ids/counts are returned, labels are attached back in TS.
-- `virtualFilters` (ticket #33, see virtual-columns.sql) is folded into the
-- same base scan via an inlined `NOT EXISTS (... virtual_filter_predicate_matches
-- ...)` (ticket #37 perf fix — same non-inlinable-SubLink timeout as
-- `company_filter_options`, not the `virtual_filters_match` wrapper), sharing
-- the exact predicate the People list/export/push seam uses.
CREATE OR REPLACE FUNCTION person_filter_options(filters jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb LANGUAGE sql STABLE AS $$
WITH params AS (
  SELECT
    NULLIF(trim(both from (filters->>'search')), '') AS search,
    NULLIF(trim(both from (filters->>'jobTitle')), '') AS job_title,
    (filters->>'employeeMin')::int AS emp_min,
    (filters->>'employeeMax')::int AS emp_max,
    COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
    COALESCE(filters->>'email', 'any') AS email_filter,
    COALESCE(filters->>'phone', 'any') AS phone_filter,
    COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
    -- Push-status filter (ticket #127), extracted once — clientId cast cast-safe
    -- via safe_uuid (virtual-columns.sql). Absent/inactive -> all NULL -> no-op.
    filters#>>'{pushStatus,status}' AS push_status_kind,
    filters#>>'{pushStatus,platform}' AS push_platform,
    safe_uuid(filters#>>'{pushStatus,clientId}') AS push_client_id,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
),
-- MATERIALIZED forces one scan of `people`, reused by all six facet
-- subqueries below instead of six independent scans.
base AS MATERIALIZED (
  -- Ticket #30: LEFT JOIN so a person with no linked company (company_id
  -- NULL) still evaluates person-sourced conditions correctly, mirroring
  -- people_matching_virtual_filters (virtual-columns.sql).
  SELECT p.niche_tokens, p.industry_id, p.country_id, p.source_tokens,
         p.employee_count, p.email_status, p.phone_type, p.email, p.phone, p.job_title
  FROM people p LEFT JOIN companies co ON co.id = p.company_id, params pr
  WHERE
    (pr.search IS NULL OR p.full_name ILIKE '%' || pr.search || '%' OR p.email ILIKE '%' || pr.search || '%')
    AND (pr.job_title IS NULL OR p.job_title ILIKE '%' || pr.job_title || '%')
    AND (
      CASE
        WHEN pr.emp_min IS NOT NULL OR pr.emp_max IS NOT NULL THEN
          (pr.emp_min IS NULL OR p.employee_count >= pr.emp_min)
          AND (pr.emp_max IS NULL OR p.employee_count <= pr.emp_max)
        WHEN jsonb_array_length(pr.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(pr.emp_ranges) AS r(min_v int, max_v int)
            WHERE p.employee_count >= r.min_v AND (r.max_v IS NULL OR p.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (pr.email_filter = 'any'
      OR (pr.email_filter = 'not_empty' AND p.email IS NOT NULL AND p.email <> '')
      OR (pr.email_filter = 'empty' AND (p.email IS NULL OR p.email = '')))
    AND (pr.phone_filter = 'any'
      OR (pr.phone_filter = 'not_empty' AND p.phone IS NOT NULL AND p.phone <> '')
      OR (pr.phone_filter = 'empty' AND (p.phone IS NULL OR p.phone = '')))
    -- Grouped virtual-filter fold (ticket #117) — keep in lockstep with all
    -- six inlined copies (virtual-columns.sql, canonical-columns.sql,
    -- enrichment-fields.sql).
    --
    -- Ticket #30: per-condition dispatch — a company-sourced condition
    -- ('source' = 'company') reads the LEFT-JOINed co.custom_data; absent
    -- source (or 'person') is byte-identical to pre-#30 behavior. People->
    -- company is one-to-one, so no quantifier is needed here (unlike the
    -- company->people fan-out in canonical-columns.sql).
    AND (
      COALESCE(jsonb_array_length(pr.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(pr.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END)
        )
      END
    )
    -- Push-status filter (ticket #127) — identical to the clause in
    -- people_matching_virtual_filters (virtual-columns.sql); keep in lockstep so
    -- the six facet counts stay scoped to the same rows the list returns.
    AND CASE pr.push_status_kind
      WHEN 'pushed' THEN EXISTS (
        SELECT 1 FROM platform_pushes pp
        WHERE pp.person_id = p.id
          AND pp.client_id = pr.push_client_id
          AND pp.platform = pr.push_platform
      )
      WHEN 'not_pushed' THEN NOT EXISTS (
        SELECT 1 FROM platform_pushes pp
        WHERE pp.person_id = p.id
          AND pp.client_id = pr.push_client_id
          AND pp.platform = pr.push_platform
      )
      ELSE true
    END
),
niches AS (
  SELECT token AS id, count(*) AS count FROM (
    SELECT unnest(base.niche_tokens) AS token
    FROM base, params
    WHERE base.niche_tokens IS NOT NULL
      AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
      AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
      AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
      AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
      AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
      AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
      AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
      AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
      AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
      AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
      AND (
        CASE
          WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
            (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
            AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
          WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
            EXISTS (
              SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
              WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
            )
          ELSE true
        END
      )
  ) t
  GROUP BY token
),
sources AS (
  SELECT token AS id, count(*) AS count FROM (
    SELECT unnest(base.source_tokens) AS token
    FROM base, params
    WHERE (cardinality(params.niche_exc) = 0 OR base.niche_tokens IS NULL OR NOT (base.niche_tokens && params.niche_exc))
      AND (cardinality(params.niche_inc) = 0 OR (base.niche_tokens IS NOT NULL AND base.niche_tokens && params.niche_inc))
      AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
      AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
      AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
      AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
      AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
      AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
      AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
      AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
      AND (
        CASE
          WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
            (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
            AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
          WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
            EXISTS (
              SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
              WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
            )
          ELSE true
        END
      )
  ) t
  GROUP BY token
),
industries AS (
  SELECT base.industry_id AS id, count(*) AS count FROM base, params
  WHERE base.industry_id IS NOT NULL
    AND (cardinality(params.niche_exc) = 0 OR base.niche_tokens IS NULL OR NOT (base.niche_tokens && params.niche_exc))
    AND (cardinality(params.niche_inc) = 0 OR (base.niche_tokens IS NOT NULL AND base.niche_tokens && params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
    AND (
      CASE
        WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
          (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
          AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
        WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
            WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
  GROUP BY base.industry_id
),
countries AS (
  SELECT base.country_id AS id, count(*) AS count FROM base, params
  WHERE base.country_id IS NOT NULL
    AND (cardinality(params.niche_exc) = 0 OR base.niche_tokens IS NULL OR NOT (base.niche_tokens && params.niche_exc))
    AND (cardinality(params.niche_inc) = 0 OR (base.niche_tokens IS NOT NULL AND base.niche_tokens && params.niche_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
    AND (
      CASE
        WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
          (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
          AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
        WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
            WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
  GROUP BY base.country_id
),
email_statuses AS (
  SELECT base.email_status AS id, count(*) AS count FROM base, params
  WHERE base.email_status IS NOT NULL AND base.email_status <> ''
    AND (cardinality(params.niche_exc) = 0 OR base.niche_tokens IS NULL OR NOT (base.niche_tokens && params.niche_exc))
    AND (cardinality(params.niche_inc) = 0 OR (base.niche_tokens IS NOT NULL AND base.niche_tokens && params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.phonetype_exc) = 0 OR base.phone_type IS NULL OR NOT (base.phone_type = ANY(params.phonetype_exc)))
    AND (cardinality(params.phonetype_inc) = 0 OR base.phone_type = ANY(params.phonetype_inc))
    AND (
      CASE
        WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
          (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
          AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
        WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
            WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
  GROUP BY base.email_status
),
phone_types AS (
  SELECT base.phone_type AS id, count(*) AS count FROM base, params
  WHERE base.phone_type IS NOT NULL AND base.phone_type <> ''
    AND (cardinality(params.niche_exc) = 0 OR base.niche_tokens IS NULL OR NOT (base.niche_tokens && params.niche_exc))
    AND (cardinality(params.niche_inc) = 0 OR (base.niche_tokens IS NOT NULL AND base.niche_tokens && params.niche_inc))
    AND (cardinality(params.country_exc) = 0 OR base.country_id IS NULL OR NOT (base.country_id = ANY(params.country_exc)))
    AND (cardinality(params.country_inc) = 0 OR base.country_id = ANY(params.country_inc))
    AND (cardinality(params.industry_exc) = 0 OR base.industry_id IS NULL OR NOT (base.industry_id = ANY(params.industry_exc)))
    AND (cardinality(params.industry_inc) = 0 OR base.industry_id = ANY(params.industry_inc))
    AND (cardinality(params.source_exc) = 0 OR base.source_tokens IS NULL OR NOT (base.source_tokens && params.source_exc))
    AND (cardinality(params.source_inc) = 0 OR (base.source_tokens IS NOT NULL AND base.source_tokens && params.source_inc))
    AND (cardinality(params.emailstatus_exc) = 0 OR base.email_status IS NULL OR NOT (base.email_status = ANY(params.emailstatus_exc)))
    AND (cardinality(params.emailstatus_inc) = 0 OR base.email_status = ANY(params.emailstatus_inc))
    AND (
      CASE
        WHEN params.emp_min IS NOT NULL OR params.emp_max IS NOT NULL THEN
          (params.emp_min IS NULL OR base.employee_count >= params.emp_min)
          AND (params.emp_max IS NULL OR base.employee_count <= params.emp_max)
        WHEN jsonb_array_length(params.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(params.emp_ranges) AS r(min_v int, max_v int)
            WHERE base.employee_count >= r.min_v AND (r.max_v IS NULL OR base.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
  GROUP BY base.phone_type
)
SELECT jsonb_build_object(
  'niches', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM niches), '[]'::jsonb),
  'sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM sources), '[]'::jsonb),
  'industries', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM industries), '[]'::jsonb),
  'countries', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM countries), '[]'::jsonb),
  'emailStatuses', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM email_statuses), '[]'::jsonb),
  'phoneTypes', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', id, 'count', count)) FROM phone_types), '[]'::jsonb)
);
$$;


-- ============================================================================
-- SECTION: lib/data/enrichment-fields.sql
-- ============================================================================

-- Run once in the Supabase SQL editor (see docs/adr/0002-virtual-column-enrichment-filtering.md,
-- issue #32, parent spec #31).
-- NOTE: run virtual-columns.sql (ticket #33) before this file — the entity
-- wrappers below call virtual_filter_predicate_matches, defined there, so an
-- already-active virtual-column filter also scopes the discovery sample,
-- exactly like it scopes company_filter_options/person_filter_options.
--
-- RPC: sampled enrichment-field discovery, scoped to the currently active
-- list filters. Backs the "Add column from enrichment" field picker — for
-- each enrichment key present in a bounded sample of the filtered set, infers
-- a filterable type (Text/Number/Boolean/List/Date) from the dominant value
-- shape and returns a capped list of distinct sample values (for a later
-- value picker). Deliberately samples rather than running
-- `DISTINCT jsonb_object_keys` over the whole table: that's a multi-second
-- full scan at ~109k rows, and the picker needs to open fast even on the
-- unfiltered table. The `LIMIT sample_size` inside each entity's `filtered`
-- CTE (below) has no ORDER BY, so Postgres can stop scanning as soon as it
-- has enough matching rows instead of materializing the whole filtered set.
--
-- Two thin entity-specific wrappers (company_enrichment_fields,
-- person_enrichment_fields) apply that entity's filters and sampling, then
-- both hand their sampled custom_data off to the shared
-- enrichment_field_discovery function below — mirroring the
-- company_filter_options / person_filter_options split in
-- canonical-columns.sql / people-canonical-columns.sql, but factoring out the
-- part that doesn't differ between entities (key/type/value discovery).

-- Housekeeping keys never surface in the picker. Mirrors isHousekeepingKey in
-- lib/data/custom-data.ts exactly (same blocklist, same `pushed_to_*` /
-- `*_at` suffix rules); `extra_blocked` lets the People wrapper layer on
-- PERSON_EXTRA_BLOCKED_KEYS the way filterCustomData's extraBlockedKeys does.
CREATE OR REPLACE FUNCTION enrichment_key_is_blocked(key text, extra_blocked text[] DEFAULT '{}'::text[])
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT
    key = ANY(ARRAY['naics', 'aiark_id', 'industries', 'legal_name', 'ai_ark_approaches',
                     'pushed_to_clay', 'created_at', 'updated_at', 'company_type'])
    OR key LIKE 'pushed_to_%'
    OR key LIKE '%\_at' ESCAPE '\'
    OR key = ANY(extra_blocked);
$$;

-- Classifies a single custom_data value into one of the five filterable
-- types, or 'Empty'. Per the ADR, real `custom_data` stores the same key as
-- different shapes across rows (numbers as strings, unit-bearing strings,
-- sentinels, unrendered Clay templates) — so string values are pattern-
-- matched, not just typeof-checked. The Number regex (`^-?[0-9.]+$`) matches
-- the cast guard virtual-column filtering uses, so a value classified Number
-- here is guaranteed castable there. Date compares/detects ISO-prefixed
-- strings only (`YYYY-MM-DD...`), consistent with the lexicographic (no-cast)
-- Date comparison the ADR decided on.
CREATE OR REPLACE FUNCTION enrichment_value_type(value jsonb)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN value IS NULL OR value = 'null'::jsonb THEN 'Empty'
    WHEN jsonb_typeof(value) = 'array' AND jsonb_array_length(value) = 0 THEN 'Empty'
    WHEN jsonb_typeof(value) = 'array' THEN 'List'
    WHEN jsonb_typeof(value) = 'boolean' THEN 'Boolean'
    WHEN jsonb_typeof(value) = 'number' THEN 'Number'
    WHEN jsonb_typeof(value) = 'object' THEN 'Text'
    ELSE (
      CASE
        WHEN trim(both from (value #>> '{}')) IN ('', '-') THEN 'Empty'
        WHEN (value #>> '{}') ~ '^\{\{.*\}\}$' THEN 'Empty'
        WHEN (value #>> '{}') ~ '^\d{4}-\d{2}-\d{2}' THEN 'Date'
        WHEN (value #>> '{}') ~ '^-?[0-9.]+$' THEN 'Number'
        WHEN lower(value #>> '{}') IN ('true', 'false') THEN 'Boolean'
        ELSE 'Text'
      END
    )
  END;
$$;

-- Shared discovery core: given an array of already-sampled, already-filtered
-- custom_data objects (one entity's `filtered` CTE, aggregated), returns
-- `[{key, type, sampleValues}]` for every non-blocklisted key present in the
-- sample. Type is the dominant (most frequent, then alphabetical to break
-- ties deterministically) non-Empty shape seen for that key; a key whose
-- every sampled value is Empty still surfaces (it's present in the sample)
-- but falls back to Text since there's no dominant shape to infer from.
-- Sample values for List keys are the individual array elements (what a
-- value picker offers), not the serialized array; for every other type it's
-- the scalar value as text. Empty values are excluded from both the type
-- vote and the sample-value list — they're not real data.
CREATE OR REPLACE FUNCTION enrichment_field_discovery(
  samples jsonb[],
  extra_blocked_keys text[] DEFAULT '{}'::text[],
  max_values_per_key int DEFAULT 25
) RETURNS jsonb LANGUAGE sql STABLE AS $$
  WITH kv AS (
    SELECT e.key, e.value
    FROM unnest(samples) AS s(custom_data),
         LATERAL jsonb_each(COALESCE(s.custom_data, '{}'::jsonb)) AS e(key, value)
    WHERE NOT enrichment_key_is_blocked(e.key, extra_blocked_keys)
  ),
  classified AS (
    SELECT key, value, enrichment_value_type(value) AS value_type
    FROM kv
  ),
  key_type_counts AS (
    SELECT key, value_type, count(*) AS n
    FROM classified
    WHERE value_type <> 'Empty'
    GROUP BY key, value_type
  ),
  key_types AS (
    SELECT DISTINCT ON (key) key, value_type AS type
    FROM key_type_counts
    ORDER BY key, n DESC, value_type ASC
  ),
  -- Flattens List values to their individual elements; every other type
  -- passes its scalar value through as text.
  value_candidates AS (
    SELECT c.key,
      CASE WHEN jsonb_typeof(c.value) = 'array' THEN elem.val ELSE (c.value #>> '{}') END AS val
    FROM classified c
    LEFT JOIN LATERAL jsonb_array_elements_text(
      CASE WHEN jsonb_typeof(c.value) = 'array' THEN c.value ELSE '[]'::jsonb END
    ) AS elem(val) ON true
    WHERE c.value_type <> 'Empty'
  ),
  distinct_values AS (
    SELECT key, val, count(*) AS n
    FROM value_candidates
    WHERE val IS NOT NULL AND trim(val) NOT IN ('', '-') AND val !~ '^\{\{.*\}\}$'
    GROUP BY key, val
  ),
  ranked_values AS (
    SELECT key, val, row_number() OVER (PARTITION BY key ORDER BY n DESC, val ASC) AS rn
    FROM distinct_values
  ),
  capped_values AS (
    SELECT key, jsonb_agg(val ORDER BY rn) AS values
    FROM ranked_values
    WHERE rn <= max_values_per_key
    GROUP BY key
  ),
  all_keys AS (SELECT DISTINCT key FROM kv)
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'key', ak.key,
      'type', COALESCE(kt.type, 'Text'),
      'sampleValues', COALESCE(cv.values, '[]'::jsonb)
    ) ORDER BY ak.key
  ), '[]'::jsonb)
  FROM all_keys ak
  LEFT JOIN key_types kt ON kt.key = ak.key
  LEFT JOIN capped_values cv ON cv.key = ak.key;
$$;

-- RPC: enrichment-field discovery scoped to the active /companies filters.
-- `filters` is the same JSON-serialized CompanyListFilters payload
-- company_filter_options takes (see lib/data/companies.ts
-- toFilterOptionsRpcPayload) — the `filtered` CTE below applies every
-- dimension at once (unlike company_filter_options' per-facet CTEs, which
-- each omit their own dimension), since discovery isn't a facet and has no
-- "exclude this filter's own contribution" concept.
CREATE OR REPLACE FUNCTION company_enrichment_fields(
  filters jsonb DEFAULT '{}'::jsonb,
  sample_size int DEFAULT 500,
  max_values_per_key int DEFAULT 25
) RETURNS jsonb LANGUAGE sql STABLE AS $$
  WITH params AS (
    SELECT
      NULLIF(trim(both from (filters->>'search')), '') AS search,
      (filters->>'employeeMin')::int AS emp_min,
      (filters->>'employeeMax')::int AS emp_max,
      COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
      COALESCE(filters->>'email', 'any') AS email_filter,
      COALESCE(filters->>'phone', 'any') AS phone_filter,
      COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
  ),
  filtered AS (
    SELECT c.custom_data
    FROM companies c, params p
    WHERE
      (p.search IS NULL OR c.company_name ILIKE '%' || p.search || '%' OR c.domain ILIKE '%' || p.search || '%')
      AND (
        CASE
          WHEN p.emp_min IS NOT NULL OR p.emp_max IS NOT NULL THEN
            (p.emp_min IS NULL OR c.employee_count >= p.emp_min)
            AND (p.emp_max IS NULL OR c.employee_count <= p.emp_max)
          WHEN jsonb_array_length(p.emp_ranges) > 0 THEN
            EXISTS (
              SELECT 1 FROM jsonb_to_recordset(p.emp_ranges) AS r(min_v int, max_v int)
              WHERE c.employee_count >= r.min_v AND (r.max_v IS NULL OR c.employee_count <= r.max_v)
            )
          ELSE true
        END
      )
      AND (p.email_filter = 'any'
        OR (p.email_filter = 'not_empty' AND c.email IS NOT NULL AND c.email <> '')
        OR (p.email_filter = 'empty' AND (c.email IS NULL OR c.email = '')))
      AND (p.phone_filter = 'any'
        OR (p.phone_filter = 'not_empty' AND c.phone IS NOT NULL AND c.phone <> '')
        OR (p.phone_filter = 'empty' AND (c.phone IS NULL OR c.phone = '')))
      AND (cardinality(p.niche_inc) = 0 OR c.niche = ANY(p.niche_inc))
      AND (cardinality(p.niche_exc) = 0 OR c.niche IS NULL OR NOT (c.niche = ANY(p.niche_exc)))
      AND (cardinality(p.source_inc) = 0 OR (c.source_tokens IS NOT NULL AND c.source_tokens && p.source_inc))
      AND (cardinality(p.source_exc) = 0 OR c.source_tokens IS NULL OR NOT (c.source_tokens && p.source_exc))
      AND (cardinality(p.industry_inc) = 0 OR c.industry_id = ANY(p.industry_inc))
      AND (cardinality(p.industry_exc) = 0 OR c.industry_id IS NULL OR NOT (c.industry_id = ANY(p.industry_exc)))
      AND (cardinality(p.country_inc) = 0 OR c.country_id = ANY(p.country_inc))
      AND (cardinality(p.country_exc) = 0 OR c.country_id IS NULL OR NOT (c.country_id = ANY(p.country_exc)))
      AND (cardinality(p.emailstatus_inc) = 0 OR c.email_status = ANY(p.emailstatus_inc))
      AND (cardinality(p.emailstatus_exc) = 0 OR c.email_status IS NULL OR NOT (c.email_status = ANY(p.emailstatus_exc)))
      AND (cardinality(p.phonetype_inc) = 0 OR c.phone_type = ANY(p.phonetype_inc))
      AND (cardinality(p.phonetype_exc) = 0 OR c.phone_type IS NULL OR NOT (c.phone_type = ANY(p.phonetype_exc)))
      -- Grouped virtual-filter fold (ticket #117) — keep in lockstep with all
      -- six inlined copies so discovery honors the same predicate as the list.
      --
      -- Ticket #30: per-condition dispatch, identical to
      -- companies_matching_virtual_filters (virtual-columns.sql) — a
      -- person-sourced condition reads this company's linked people.
      AND (
        COALESCE(jsonb_array_length(p.virtual_filters->'groups'), 0) = 0
        OR CASE WHEN COALESCE(p.virtual_filters->>'combinator', 'and') = 'or' THEN
          EXISTS (
            SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
            WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
                EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE (CASE
                          WHEN COALESCE(cond->>'source','company') = 'person' THEN
                            CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                              EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                              AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                            ELSE
                              EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                            END
                          ELSE
                            virtual_filter_predicate_matches(c.custom_data, cond)
                          END))
              ELSE
                NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                            WHERE NOT (CASE
                              WHEN COALESCE(cond->>'source','company') = 'person' THEN
                                CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                  EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                  AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                                ELSE
                                  EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                                END
                              ELSE
                                virtual_filter_predicate_matches(c.custom_data, cond)
                              END))
              END
          )
        ELSE
          NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(p.virtual_filters->'groups') AS grp
            WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
                EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE (CASE
                          WHEN COALESCE(cond->>'source','company') = 'person' THEN
                            CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                              EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                              AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                            ELSE
                              EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                            END
                          ELSE
                            virtual_filter_predicate_matches(c.custom_data, cond)
                          END))
              ELSE
                NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                            WHERE NOT (CASE
                              WHEN COALESCE(cond->>'source','company') = 'person' THEN
                                CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                  EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                  AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                                ELSE
                                  EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                                END
                              ELSE
                                virtual_filter_predicate_matches(c.custom_data, cond)
                              END))
              END)
          )
        END
      )
    LIMIT sample_size
  )
  SELECT jsonb_build_object(
    'fields', enrichment_field_discovery(
      (SELECT COALESCE(array_agg(custom_data), ARRAY[]::jsonb[]) FROM filtered),
      ARRAY[]::text[],
      max_values_per_key
    ),
    'sampledRows', (SELECT count(*) FROM filtered)
  );
$$;

-- RPC: same as company_enrichment_fields but scoped to /people. `filters` is
-- the person_filter_options payload (lib/data/people.ts
-- toFilterOptionsRpcPayload, note: also carries jobTitle). Blocks
-- PERSON_EXTRA_BLOCKED_KEYS (lib/data/people.ts) in addition to the shared
-- blocklist, mirroring filterCustomData(data.custom_data,
-- PERSON_EXTRA_BLOCKED_KEYS) on the People Detail read path.
CREATE OR REPLACE FUNCTION person_enrichment_fields(
  filters jsonb DEFAULT '{}'::jsonb,
  sample_size int DEFAULT 500,
  max_values_per_key int DEFAULT 25
) RETURNS jsonb LANGUAGE sql STABLE AS $$
  WITH params AS (
    SELECT
      NULLIF(trim(both from (filters->>'search')), '') AS search,
      NULLIF(trim(both from (filters->>'jobTitle')), '') AS job_title,
      (filters->>'employeeMin')::int AS emp_min,
      (filters->>'employeeMax')::int AS emp_max,
      COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
      COALESCE(filters->>'email', 'any') AS email_filter,
      COALESCE(filters->>'phone', 'any') AS phone_filter,
      COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
  ),
  filtered AS (
    -- Ticket #30: LEFT JOIN so a person with no linked company still
    -- evaluates person-sourced conditions correctly, mirroring
    -- people_matching_virtual_filters (virtual-columns.sql).
    SELECT p.custom_data
    FROM people p LEFT JOIN companies co ON co.id = p.company_id, params pr
    WHERE
      (pr.search IS NULL OR p.full_name ILIKE '%' || pr.search || '%' OR p.email ILIKE '%' || pr.search || '%')
      AND (pr.job_title IS NULL OR p.job_title ILIKE '%' || pr.job_title || '%')
      AND (
        CASE
          WHEN pr.emp_min IS NOT NULL OR pr.emp_max IS NOT NULL THEN
            (pr.emp_min IS NULL OR p.employee_count >= pr.emp_min)
            AND (pr.emp_max IS NULL OR p.employee_count <= pr.emp_max)
          WHEN jsonb_array_length(pr.emp_ranges) > 0 THEN
            EXISTS (
              SELECT 1 FROM jsonb_to_recordset(pr.emp_ranges) AS r(min_v int, max_v int)
              WHERE p.employee_count >= r.min_v AND (r.max_v IS NULL OR p.employee_count <= r.max_v)
            )
          ELSE true
        END
      )
      AND (pr.email_filter = 'any'
        OR (pr.email_filter = 'not_empty' AND p.email IS NOT NULL AND p.email <> '')
        OR (pr.email_filter = 'empty' AND (p.email IS NULL OR p.email = '')))
      AND (pr.phone_filter = 'any'
        OR (pr.phone_filter = 'not_empty' AND p.phone IS NOT NULL AND p.phone <> '')
        OR (pr.phone_filter = 'empty' AND (p.phone IS NULL OR p.phone = '')))
      AND (cardinality(pr.niche_inc) = 0 OR (p.niche_tokens IS NOT NULL AND p.niche_tokens && pr.niche_inc))
      AND (cardinality(pr.niche_exc) = 0 OR p.niche_tokens IS NULL OR NOT (p.niche_tokens && pr.niche_exc))
      AND (cardinality(pr.source_inc) = 0 OR (p.source_tokens IS NOT NULL AND p.source_tokens && pr.source_inc))
      AND (cardinality(pr.source_exc) = 0 OR p.source_tokens IS NULL OR NOT (p.source_tokens && pr.source_exc))
      AND (cardinality(pr.industry_inc) = 0 OR p.industry_id = ANY(pr.industry_inc))
      AND (cardinality(pr.industry_exc) = 0 OR p.industry_id IS NULL OR NOT (p.industry_id = ANY(pr.industry_exc)))
      AND (cardinality(pr.country_inc) = 0 OR p.country_id = ANY(pr.country_inc))
      AND (cardinality(pr.country_exc) = 0 OR p.country_id IS NULL OR NOT (p.country_id = ANY(pr.country_exc)))
      AND (cardinality(pr.emailstatus_inc) = 0 OR p.email_status = ANY(pr.emailstatus_inc))
      AND (cardinality(pr.emailstatus_exc) = 0 OR p.email_status IS NULL OR NOT (p.email_status = ANY(pr.emailstatus_exc)))
      AND (cardinality(pr.phonetype_inc) = 0 OR p.phone_type = ANY(pr.phonetype_inc))
      AND (cardinality(pr.phonetype_exc) = 0 OR p.phone_type IS NULL OR NOT (p.phone_type = ANY(pr.phonetype_exc)))
      -- Grouped virtual-filter fold (ticket #117) — keep in lockstep with all
      -- six inlined copies so discovery honors the same predicate as the list.
      --
      -- Ticket #30: per-condition dispatch, identical to
      -- people_matching_virtual_filters (virtual-columns.sql) — a
      -- company-sourced condition reads the LEFT-JOINed co.custom_data.
      AND (
        COALESCE(jsonb_array_length(pr.virtual_filters->'groups'), 0) = 0
        OR CASE WHEN COALESCE(pr.virtual_filters->>'combinator', 'and') = 'or' THEN
          EXISTS (
            SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
            WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
                EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE (CASE
                          WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                          ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                          END))
              ELSE
                NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                            WHERE NOT (CASE
                              WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                              ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                              END))
              END
          )
        ELSE
          NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
            WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
                EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                        WHERE (CASE
                          WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                          ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                          END))
              ELSE
                NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                            WHERE NOT (CASE
                              WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                              ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                              END))
              END)
          )
        END
      )
    LIMIT sample_size
  )
  SELECT jsonb_build_object(
    'fields', enrichment_field_discovery(
      (SELECT COALESCE(array_agg(custom_data), ARRAY[]::jsonb[]) FROM filtered),
      ARRAY['company_linkedin_id', 'connections_count', 'apollo_id'],
      max_values_per_key
    ),
    'sampledRows', (SELECT count(*) FROM filtered)
  );
$$;


-- ============================================================================
-- SECTION: lib/data/push-status-counts.sql
-- ============================================================================

-- Run once in the Supabase SQL editor (Push Status Filters epic #125, E1 / issue #133).
-- NOTE: on a fresh database, run virtual-columns.sql, canonical-columns.sql, and
-- people-canonical-columns.sql before this file — the two functions below reuse
-- the same base-scan predicates (and virtual_filter_predicate_matches) those files
-- define, and read the canonical columns those files add.
--
-- Phase 2 of the push-status filter: live per-option preview counts for the
-- popover. Given the current filter set (every *other* active filter) plus a
-- selected client + platform, return { pushed, notPushed } so the operator can
-- see "Not yet pushed (3,000) / Already pushed (1,000)" before committing.
--
-- Deliberately a *separate* lightweight RPC rather than folding push counts into
-- the 6-facet *_filter_options functions: these counts are only needed while the
-- popover is open with a client selected, not on every page render. The push
-- status dimension is "self-excluded" (like a facet's own count) — the scan
-- applies every base + facet filter EXCEPT push status, then splits the surviving
-- rows into pushed vs not-pushed for the given client/platform. So
-- `pushed + notPushed` equals the total the filter would yield for that
-- client/platform, matching what applying the filter actually returns.

-- People: person-level push semantics — a person is "pushed" iff a platform_pushes
-- row exists for (person, client, platform). Mirrors the predicate in
-- person_filter_options / people_matching_virtual_filters; keep in lockstep so the
-- preview counts match what the filter yields.
CREATE OR REPLACE FUNCTION person_push_status_counts(
  filters jsonb DEFAULT '{}'::jsonb,
  client_id uuid DEFAULT NULL,
  platform text DEFAULT NULL
)
RETURNS jsonb LANGUAGE sql STABLE AS $$
WITH params AS (
  SELECT
    NULLIF(trim(both from (filters->>'search')), '') AS search,
    NULLIF(trim(both from (filters->>'jobTitle')), '') AS job_title,
    (filters->>'employeeMin')::int AS emp_min,
    (filters->>'employeeMax')::int AS emp_max,
    COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
    COALESCE(filters->>'email', 'any') AS email_filter,
    COALESCE(filters->>'phone', 'any') AS phone_filter,
    COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
    -- The client + platform being previewed (function args aliased here so the
    -- count subqueries reference them qualified as pr.*, never an ambiguous bare
    -- `platform` that could collide with platform_pushes.platform).
    client_id AS push_client_id,
    platform AS push_platform,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
),
-- Every active filter EXCEPT push status (the dimension being previewed), so the
-- surviving rows are exactly what the rest of the view already narrows to. The
-- base clauses mirror person_filter_options' `base`; the six facet clauses mirror
-- its per-facet subqueries. Push status is intentionally omitted here.
scoped AS (
  SELECT
    EXISTS (
      SELECT 1 FROM platform_pushes pp
      WHERE pp.person_id = p.id
        AND pp.client_id = pr.push_client_id
        AND pp.platform = pr.push_platform
    ) AS is_pushed
  -- Ticket #30: LEFT JOIN so a person with no linked company still
  -- evaluates person-sourced conditions correctly, mirroring
  -- people_matching_virtual_filters (virtual-columns.sql).
  FROM people p LEFT JOIN companies co ON co.id = p.company_id, params pr
  WHERE
    (pr.search IS NULL OR p.full_name ILIKE '%' || pr.search || '%' OR p.email ILIKE '%' || pr.search || '%')
    AND (pr.job_title IS NULL OR p.job_title ILIKE '%' || pr.job_title || '%')
    AND (
      CASE
        WHEN pr.emp_min IS NOT NULL OR pr.emp_max IS NOT NULL THEN
          (pr.emp_min IS NULL OR p.employee_count >= pr.emp_min)
          AND (pr.emp_max IS NULL OR p.employee_count <= pr.emp_max)
        WHEN jsonb_array_length(pr.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(pr.emp_ranges) AS r(min_v int, max_v int)
            WHERE p.employee_count >= r.min_v AND (r.max_v IS NULL OR p.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (pr.email_filter = 'any'
      OR (pr.email_filter = 'not_empty' AND p.email IS NOT NULL AND p.email <> '')
      OR (pr.email_filter = 'empty' AND (p.email IS NULL OR p.email = '')))
    AND (pr.phone_filter = 'any'
      OR (pr.phone_filter = 'not_empty' AND p.phone IS NOT NULL AND p.phone <> '')
      OR (pr.phone_filter = 'empty' AND (p.phone IS NULL OR p.phone = '')))
    -- Grouped virtual-filter fold (ticket #117) — identical to the copies in
    -- people-canonical-columns.sql / virtual-columns.sql; keep in lockstep.
    --
    -- Ticket #30: per-condition dispatch, identical to person_filter_options
    -- (people-canonical-columns.sql) — a company-sourced condition reads the
    -- LEFT-JOINed co.custom_data.
    AND (
      COALESCE(jsonb_array_length(pr.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(pr.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                        ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','person') = 'company' THEN virtual_filter_predicate_matches(co.custom_data, cond)
                            ELSE virtual_filter_predicate_matches(p.custom_data, cond)
                            END))
            END)
        )
      END
    )
    -- Six facet dimensions, applied in full (unlike filter_options, no self is
    -- excluded here — the excluded dimension is push status, not a facet).
    AND (cardinality(pr.niche_exc) = 0 OR p.niche_tokens IS NULL OR NOT (p.niche_tokens && pr.niche_exc))
    AND (cardinality(pr.niche_inc) = 0 OR (p.niche_tokens IS NOT NULL AND p.niche_tokens && pr.niche_inc))
    AND (cardinality(pr.source_exc) = 0 OR p.source_tokens IS NULL OR NOT (p.source_tokens && pr.source_exc))
    AND (cardinality(pr.source_inc) = 0 OR (p.source_tokens IS NOT NULL AND p.source_tokens && pr.source_inc))
    AND (cardinality(pr.industry_exc) = 0 OR p.industry_id IS NULL OR NOT (p.industry_id = ANY(pr.industry_exc)))
    AND (cardinality(pr.industry_inc) = 0 OR p.industry_id = ANY(pr.industry_inc))
    AND (cardinality(pr.country_exc) = 0 OR p.country_id IS NULL OR NOT (p.country_id = ANY(pr.country_exc)))
    AND (cardinality(pr.country_inc) = 0 OR p.country_id = ANY(pr.country_inc))
    AND (cardinality(pr.emailstatus_exc) = 0 OR p.email_status IS NULL OR NOT (p.email_status = ANY(pr.emailstatus_exc)))
    AND (cardinality(pr.emailstatus_inc) = 0 OR p.email_status = ANY(pr.emailstatus_inc))
    AND (cardinality(pr.phonetype_exc) = 0 OR p.phone_type IS NULL OR NOT (p.phone_type = ANY(pr.phonetype_exc)))
    AND (cardinality(pr.phonetype_inc) = 0 OR p.phone_type = ANY(pr.phonetype_inc))
)
SELECT jsonb_build_object(
  'pushed', COALESCE(count(*) FILTER (WHERE is_pushed), 0),
  'notPushed', COALESCE(count(*) FILTER (WHERE NOT is_pushed), 0)
) FROM scoped;
$$;

-- Companies: "has work left" semantics — a company is "not yet pushed" (has work
-- left) iff it has at least one linked person not yet pushed for this
-- client/platform, and "already pushed" iff it has people AND none of them still
-- need pushing. A company with zero linked people counts as neither (identical to
-- company_filter_options' push-status clause). Keep in lockstep with that clause.
CREATE OR REPLACE FUNCTION company_push_status_counts(
  filters jsonb DEFAULT '{}'::jsonb,
  client_id uuid DEFAULT NULL,
  platform text DEFAULT NULL
)
RETURNS jsonb LANGUAGE sql STABLE AS $$
WITH params AS (
  SELECT
    NULLIF(trim(both from (filters->>'search')), '') AS search,
    (filters->>'employeeMin')::int AS emp_min,
    (filters->>'employeeMax')::int AS emp_max,
    COALESCE(filters->'employeeBucketRanges', '[]'::jsonb) AS emp_ranges,
    COALESCE(filters->>'email', 'any') AS email_filter,
    COALESCE(filters->>'phone', 'any') AS phone_filter,
    COALESCE(filters->'virtualFilters', '{}'::jsonb) AS virtual_filters,
    client_id AS push_client_id,
    platform AS push_platform,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,include}', '[]'::jsonb))) AS niche_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{niche,exclude}', '[]'::jsonb))) AS niche_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,include}', '[]'::jsonb))) AS source_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{source,exclude}', '[]'::jsonb))) AS source_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,include}', '[]'::jsonb))) AS industry_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{industry,exclude}', '[]'::jsonb))) AS industry_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,include}', '[]'::jsonb))) AS country_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{country,exclude}', '[]'::jsonb))) AS country_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,include}', '[]'::jsonb))) AS emailstatus_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{emailStatus,exclude}', '[]'::jsonb))) AS emailstatus_exc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,include}', '[]'::jsonb))) AS phonetype_inc,
    ARRAY(SELECT jsonb_array_elements_text(COALESCE(filters#>'{phoneType,exclude}', '[]'::jsonb))) AS phonetype_exc
),
scoped AS (
  SELECT
    EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id) AS has_people,
    EXISTS (
      SELECT 1 FROM people pe
      WHERE pe.company_id = c.id
        AND NOT EXISTS (
          SELECT 1 FROM platform_pushes pp
          WHERE pp.person_id = pe.id
            AND pp.client_id = pr.push_client_id
            AND pp.platform = pr.push_platform
        )
    ) AS has_work_left
  FROM companies c, params pr
  WHERE
    (pr.search IS NULL OR c.company_name ILIKE '%' || pr.search || '%' OR c.domain ILIKE '%' || pr.search || '%')
    AND (
      CASE
        WHEN pr.emp_min IS NOT NULL OR pr.emp_max IS NOT NULL THEN
          (pr.emp_min IS NULL OR c.employee_count >= pr.emp_min)
          AND (pr.emp_max IS NULL OR c.employee_count <= pr.emp_max)
        WHEN jsonb_array_length(pr.emp_ranges) > 0 THEN
          EXISTS (
            SELECT 1 FROM jsonb_to_recordset(pr.emp_ranges) AS r(min_v int, max_v int)
            WHERE c.employee_count >= r.min_v AND (r.max_v IS NULL OR c.employee_count <= r.max_v)
          )
        ELSE true
      END
    )
    AND (pr.email_filter = 'any'
      OR (pr.email_filter = 'not_empty' AND c.email IS NOT NULL AND c.email <> '')
      OR (pr.email_filter = 'empty' AND (c.email IS NULL OR c.email = '')))
    AND (pr.phone_filter = 'any'
      OR (pr.phone_filter = 'not_empty' AND c.phone IS NOT NULL AND c.phone <> '')
      OR (pr.phone_filter = 'empty' AND (c.phone IS NULL OR c.phone = '')))
    -- Ticket #30: per-condition dispatch, identical to company_filter_options
    -- (canonical-columns.sql) — a person-sourced condition reads this
    -- company's linked people.
    AND (
      COALESCE(jsonb_array_length(pr.virtual_filters->'groups'), 0) = 0
      OR CASE WHEN COALESCE(pr.virtual_filters->>'combinator', 'and') = 'or' THEN
        EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END
        )
      ELSE
        NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(pr.virtual_filters->'groups') AS grp
          WHERE NOT (CASE WHEN COALESCE(grp->>'combinator', 'and') = 'or' THEN
              EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                      WHERE (CASE
                        WHEN COALESCE(cond->>'source','company') = 'person' THEN
                          CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                            AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                          ELSE
                            EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                          END
                        ELSE
                          virtual_filter_predicate_matches(c.custom_data, cond)
                        END))
            ELSE
              NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(grp->'conditions', '[]'::jsonb)) AS cond
                          WHERE NOT (CASE
                            WHEN COALESCE(cond->>'source','company') = 'person' THEN
                              CASE WHEN COALESCE(cond->>'quantifier','any') = 'all' THEN
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id)
                                AND NOT EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND NOT virtual_filter_predicate_matches(pe.custom_data, cond))
                              ELSE
                                EXISTS (SELECT 1 FROM people pe WHERE pe.company_id = c.id AND virtual_filter_predicate_matches(pe.custom_data, cond))
                              END
                            ELSE
                              virtual_filter_predicate_matches(c.custom_data, cond)
                            END))
            END)
        )
      END
    )
    AND (cardinality(pr.niche_exc) = 0 OR c.niche IS NULL OR NOT (c.niche = ANY(pr.niche_exc)))
    AND (cardinality(pr.niche_inc) = 0 OR c.niche = ANY(pr.niche_inc))
    AND (cardinality(pr.source_exc) = 0 OR c.source_tokens IS NULL OR NOT (c.source_tokens && pr.source_exc))
    AND (cardinality(pr.source_inc) = 0 OR (c.source_tokens IS NOT NULL AND c.source_tokens && pr.source_inc))
    AND (cardinality(pr.industry_exc) = 0 OR c.industry_id IS NULL OR NOT (c.industry_id = ANY(pr.industry_exc)))
    AND (cardinality(pr.industry_inc) = 0 OR c.industry_id = ANY(pr.industry_inc))
    AND (cardinality(pr.country_exc) = 0 OR c.country_id IS NULL OR NOT (c.country_id = ANY(pr.country_exc)))
    AND (cardinality(pr.country_inc) = 0 OR c.country_id = ANY(pr.country_inc))
    AND (cardinality(pr.emailstatus_exc) = 0 OR c.email_status IS NULL OR NOT (c.email_status = ANY(pr.emailstatus_exc)))
    AND (cardinality(pr.emailstatus_inc) = 0 OR c.email_status = ANY(pr.emailstatus_inc))
    AND (cardinality(pr.phonetype_exc) = 0 OR c.phone_type IS NULL OR NOT (c.phone_type = ANY(pr.phonetype_exc)))
    AND (cardinality(pr.phonetype_inc) = 0 OR c.phone_type = ANY(pr.phonetype_inc))
)
SELECT jsonb_build_object(
  -- not_pushed == has work left; pushed == has people AND no work left.
  'notPushed', COALESCE(count(*) FILTER (WHERE has_work_left), 0),
  'pushed', COALESCE(count(*) FILTER (WHERE has_people AND NOT has_work_left), 0)
) FROM scoped;
$$;

